INSERT INTO "notification_templates" ("id", "key", "name", "subject", "body", "waTemplateName", "waLanguage", "waCategory", "channels", "version", "isActive", "updatedAt") VALUES ('cmw68e8r5001r7v7dl2xqsap2', 'admission.confirmed', 'Admission confirmed', 'Welcome to Nexora Academy, {{name}}!', 'Hi {{name}}, your admission to {{course}} ({{batch}}) is confirmed. Student ID: {{studentCode}}. Activate your student portal account (username {{username}}) with this single-use link, valid {{hours}} hours: {{link}}', NULL, 'en', 'UTILITY', '["EMAIL","WHATSAPP"]', 1, 1, '2026-11-07T09:59:03.377+00:00') ON CONFLICT DO NOTHING;
