INSERT INTO "notification_templates" ("id", "key", "name", "subject", "body", "waTemplateName", "waLanguage", "waCategory", "channels", "version", "isActive", "updatedAt") VALUES ('cmw68e8tb001t7v7d2gt3r73d', 'enquiry.received', 'Enquiry received', 'Thanks for contacting Nexora Academy', 'Hi {{name}}, thank you for your interest in Nexora Academy! A counselor will reach out shortly. Reply here on WhatsApp for any questions.', NULL, 'en', 'UTILITY', '["IN_APP","EMAIL","WHATSAPP"]', 1, 1, '2026-11-07T09:59:03.455+00:00') ON CONFLICT DO NOTHING;
