INSERT INTO "notification_templates" ("id", "key", "name", "subject", "body", "waTemplateName", "waLanguage", "waCategory", "channels", "version", "isActive", "updatedAt") VALUES ('cmw68e8vu001v7v7djk5tkrpz', 'fee.reminder_upcoming', 'Fee reminder (upcoming)', 'Fee installment due on {{dueDate}}', 'Hi {{name}}, a gentle reminder that installment #{{installment}} of ₹{{amount}} is due on {{dueDate}}. Please ignore if already paid.', NULL, 'en', 'UTILITY', '["IN_APP","EMAIL","WHATSAPP"]', 1, 1, '2026-11-07T09:59:03.546+00:00') ON CONFLICT DO NOTHING;
